+TextureStreaming::MaterialFeedbackBuffer::~MaterialFeedbackBuffer() {
+	if (buffer.is_valid()) {
+		RS::get_singleton()->call_on_render_thread(callable_mp(RD::get_singleton(), &RD::free_rid).bind(buffer));
+	}
+
+	buffer = RID();
+	buffer_size = 0;
+	rid_map.clear();
+}
